import { Component, computed, input, model, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  TablerIconComponent, IconChevronUp, IconChevronDown, IconCircleCheckFilled,
} from '@tabler/icons-angular';
import { HrmProgress } from '../feedback/hrm-progress';
import { HrmInput } from '../data-entry/hrm-input';
import { HrmTextarea } from '../data-entry/hrm-textarea';
import { HrmSelect } from '../data-entry/hrm-select';
import { HrmSwitch } from '../data-entry/hrm-switch';
import { HrmDatePicker } from '../data-entry/hrm-date-picker';
import { HrmInputNumber } from '../data-entry/hrm-input-number';
import { HrmOption } from '../shared/hrm-option';

/** 1 field trong 1 nhóm bước. type: text · textarea · select · toggle · date · number. */
export interface HrmSetupField {
  key: string;
  label: string;
  type: 'text' | 'textarea' | 'select' | 'toggle' | 'date' | 'number';
  placeholder?: string;
  hint?: string;
  options?: HrmOption[];
  /** Field chiếm nửa hàng (2 field/hàng) — form đăng ký gọn hơn. Toggle/textarea luôn full. */
  half?: boolean;
}
/** 1 nhóm bước (section) — có form field/toggle điền trực tiếp; bấm VÒNG TRÒN → tick xong TẠI CHỖ. */
export interface HrmSetupSection {
  key: string;
  title: string;
  desc?: string;
  fields?: HrmSetupField[];
  done?: boolean;
}

/**
 * hrm-setup-guide — thẻ HƯỚNG DẪN THIẾT LẬP TƯƠNG TÁC (onboarding wizard) kiểu Shopify "Get ready to sell":
 * tiêu đề (trái) · tiến độ "x/y" + nút thu/mở (phải) — accordion các NHÓM; mỗi nhóm có FORM (field/toggle)
 * điền trực tiếp, bấm VÒNG TRÒN kế title → tick hoàn tất TẠI CHỖ (không đổi thứ tự). Data-driven ([sections]).
 * Toàn token → tự Light/Dark.
 */
@Component({
  selector: 'hrm-setup-guide',
  imports: [
    FormsModule, TablerIconComponent, HrmProgress,
    HrmInput, HrmTextarea, HrmSelect, HrmSwitch, HrmDatePicker, HrmInputNumber,
  ],
  template: `
    <div class="sg-card">
      <!-- HEADER — TRÁI: tiêu đề + mô tả · PHẢI: tiến độ kế nút thu/mở (chevron canh giữa). -->
      <button type="button" class="sg-head" (click)="collapsed.set(!collapsed())">
        <span class="sg-head-main">
          <span class="sg-title">{{ title() }}</span>
          @if (subtitle()) { <span class="sg-sub">{{ subtitle() }}</span> }
        </span>
        <span class="sg-head-right">
          <span class="sg-progress">
            <span class="sg-count">{{ doneCount() }}/{{ totalCount() }} {{ completedLabel() }}</span>
            <hrm-progress class="sg-bar" [percent]="percent()" type="line" size="small" [showInfo]="false" />
          </span>
          <tabler-icon class="sg-chev" [icon]="collapsed() ? chevDown : chevUp" [size]="18" />
        </span>
      </button>

      @if (!collapsed()) {
        <div class="sg-sections">
          @for (s of sections(); track s.key) {
            <section class="sg-sec" [class.is-open]="openSection() === s.key" [class.is-done]="isDone(s.key)">
              <button type="button" class="sg-sec-head" (click)="openSectionSet(s.key)">
                <span class="sg-sec-l">
                  <span class="sg-circle sg-circle--btn" [class.is-done]="isDone(s.key)"
                    role="button" [attr.aria-pressed]="isDone(s.key)" [attr.aria-label]="'Đánh dấu hoàn tất: ' + s.title"
                    (click)="toggleDone(s.key, $event)">
                    @if (isDone(s.key)) { <tabler-icon [icon]="icDoneCircle" [size]="20" /> }
                    @else { <tabler-icon class="sg-circle-hover" [icon]="icDoneCircle" [size]="13" /> }
                  </span>
                  <span class="sg-sec-title" [class.is-done]="isDone(s.key)">{{ s.title }}</span>
                </span>
                <tabler-icon [icon]="openSection() === s.key ? chevUp : chevDown" [size]="18" />
              </button>

              @if (openSection() === s.key) {
                <div class="sg-form">
                  @if (s.desc) { <p class="sg-form-desc">{{ s.desc }}</p> }
                  <div class="sg-grid">
                    @for (f of s.fields ?? []; track f.key) {
                      @if (f.type === 'toggle') {
                        <div class="sgf-toggle sgf-full">
                          <span class="sgf-toggle-main">
                            <span class="sgf-lbl">{{ f.label }}</span>
                            @if (f.hint) { <span class="sgf-hint">{{ f.hint }}</span> }
                          </span>
                          <hrm-switch [ngModel]="$any(val(s.key, f.key)) || false" (ngModelChange)="setVal(s.key, f.key, $event)" />
                        </div>
                      } @else {
                        <div class="sgf-field" [class.sgf-full]="f.type === 'textarea' || !f.half">
                          <label class="sgf-lbl">{{ f.label }}</label>
                          @switch (f.type) {
                            @case ('textarea') {
                              <hrm-textarea [placeholder]="f.placeholder ?? ''" [ngModel]="$any(val(s.key, f.key)) || ''" (ngModelChange)="setVal(s.key, f.key, $event)" />
                            }
                            @case ('select') {
                              <hrm-select [options]="f.options ?? []" [placeholder]="f.placeholder ?? '— Chọn —'" [ngModel]="val(s.key, f.key)" (ngModelChange)="setVal(s.key, f.key, $event)" />
                            }
                            @case ('date') {
                              <hrm-date-picker [placeholder]="f.placeholder ?? ''" [ngModel]="$any(val(s.key, f.key))" (ngModelChange)="setVal(s.key, f.key, $event)" />
                            }
                            @case ('number') {
                              <hrm-input-number [ngModel]="$any(val(s.key, f.key))" (ngModelChange)="setVal(s.key, f.key, $event)" />
                            }
                            @default {
                              <hrm-input [placeholder]="f.placeholder ?? ''" [ngModel]="$any(val(s.key, f.key)) || ''" (ngModelChange)="setVal(s.key, f.key, $event)" />
                            }
                          }
                          @if (f.hint) { <span class="sgf-hint">{{ f.hint }}</span> }
                        </div>
                      }
                    }
                  </div>
                </div>
              }
            </section>
          }
        </div>
      }
    </div>
  `,
  host: { class: 'hrm-setup-guide' },
  styles: [`
    :host { display: block; }
    .sg-card { background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-xl, 16px); overflow: hidden; }

    /* HEADER — trái main / phải (progress + chevron), canh giữa dọc → chevron giữa chiều cao header. */
    .sg-head { width: 100%; display: flex; align-items: center; gap: var(--space-4, 16px);
      padding: var(--space-4, 16px) var(--space-5, 20px); border: 0; background: transparent; cursor: pointer; text-align: left; font: inherit;
      transition: background var(--duration-fast, .15s) var(--ease-out, ease); }
    .sg-head:hover { background: var(--bg-surface-subtle); }
    .sg-head-main { flex: 1; min-width: 0; display: flex; flex-direction: column; }
    .sg-title { font-size: var(--fs-16, 16px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .sg-sub { font-size: var(--fs-13, 13px); color: var(--text-sub); margin-top: 2px; }
    .sg-head-right { flex: none; display: flex; align-items: center; gap: var(--space-3, 12px); }
    .sg-progress { display: flex; align-items: center; gap: var(--space-2, 8px); }
    .sg-count { font-size: var(--fs-13, 13px); color: var(--text-sub); white-space: nowrap; }
    .sg-bar { display: block; width: 132px; }
    .sg-chev { flex: none; color: var(--text-soft); }

    /* SECTION (accordion) */
    .sg-sec { border-top: 1px solid var(--border-soft, var(--border-sub)); }
    .sg-sec-head { width: 100%; display: flex; align-items: center; justify-content: space-between; gap: var(--space-2, 8px);
      padding: var(--space-3-5, 14px) var(--space-5, 20px); border: 0; background: transparent; cursor: pointer; text-align: left; font: inherit; color: var(--text-strong);
      transition: background var(--duration-fast, .15s) var(--ease-out, ease); }
    .sg-sec-head:hover { background: var(--bg-surface-subtle); }
    .sg-sec-l { display: flex; align-items: center; gap: var(--space-2-5, 10px); min-width: 0; }
    .sg-sec-title { font-size: var(--fs-14, 14px); font-weight: var(--font-semibold, 600); }
    .sg-sec-title.is-done { color: var(--text-sub); }
    .sg-sec-head > tabler-icon { color: var(--text-soft); }
    /* Vòng tròn check: viền đứt (chưa) / ✓ xanh (xong) — TÍCH TẠI CHỖ, không đổi thứ tự. */
    .sg-circle { flex: none; width: 20px; height: 20px; border-radius: 50%; border: 2px dashed var(--border-strong, var(--border-sub)); display: grid; place-items: center; color: var(--success-base); }
    .sg-circle.is-done { border: 0; color: var(--success-base); }
    .sg-circle--btn { cursor: pointer; transition: border-color var(--duration-fast, .15s) var(--ease-out, ease); }
    .sg-circle--btn:not(.is-done):hover { border-color: var(--success-base); }
    .sg-circle-hover { opacity: 0; transition: opacity var(--duration-fast, .15s) var(--ease-out, ease); }
    .sg-circle--btn:hover .sg-circle-hover { opacity: .4; }

    /* FORM trong nhóm đang mở — lưới 2 cột (field half) cho form nhiều thông tin gọn gàng. */
    .sg-form { padding: 0 var(--space-5, 20px) var(--space-4, 16px) calc(var(--space-5, 20px) + 30px); }
    .sg-form-desc { margin: 0 0 var(--space-3, 12px); font-size: var(--fs-13, 13px); color: var(--text-sub); line-height: 1.5; }
    .sg-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-3-5, 14px); }
    .sgf-full { grid-column: 1 / -1; }
    .sgf-field { display: flex; flex-direction: column; gap: var(--space-1-5, 6px); min-width: 0; }
    .sgf-lbl { font-size: var(--fs-13, 13px); font-weight: var(--font-medium, 500); color: var(--text-strong); }
    .sgf-hint { font-size: var(--fs-12, 12px); color: var(--text-soft); }
    .sgf-toggle { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3, 12px);
      padding: var(--space-2-5, 10px) var(--space-3, 12px); border: 1px solid var(--border-sub); border-radius: var(--radius-md); }
    .sgf-toggle-main { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
  `],
})
export class HrmSetupGuide {
  readonly title = input('Hướng dẫn thiết lập');
  readonly subtitle = input('');
  readonly completedLabel = input('hoàn thành');
  readonly sections = input<HrmSetupSection[]>([]);
  readonly collapsed = model(false);
  /** Phát khi tick/bỏ tick 1 nhóm: { section, done }. */
  readonly toggle = output<{ section: string; done: boolean }>();
  /** Phát khi đổi giá trị 1 field. */
  readonly fieldChange = output<{ section: string; field: string; value: unknown }>();

  protected readonly chevUp = IconChevronUp;
  protected readonly chevDown = IconChevronDown;
  protected readonly icDoneCircle = IconCircleCheckFilled;

  /** Giá trị field: sectionKey → fieldKey → value. */
  private readonly values = signal<Record<string, Record<string, unknown>>>({});
  protected val(s: string, f: string): unknown { return (this.values()[s] ?? {})[f]; }
  protected setVal(s: string, f: string, v: unknown): void {
    this.values.update((m) => ({ ...m, [s]: { ...(m[s] ?? {}), [f]: v } }));
    this.fieldChange.emit({ section: s, field: f, value: v });
  }

  /** Nhóm đã tick (ghi đè; mặc định lấy từ sections[].done) — TÍCH TẠI CHỖ, KHÔNG đổi thứ tự. */
  private readonly doneOverride = signal<Set<string> | null>(null);
  private readonly doneKeys = computed<Set<string>>(() =>
    this.doneOverride() ?? new Set(this.sections().filter((s) => s.done).map((s) => s.key)));
  protected isDone(k: string): boolean { return this.doneKeys().has(k); }
  protected toggleDone(k: string, e: Event): void {
    e.stopPropagation();
    const s = new Set(this.doneKeys());
    const now = !s.has(k);
    if (now) s.add(k); else s.delete(k);
    this.doneOverride.set(s);
    this.toggle.emit({ section: k, done: now });
  }

  /** Nhóm đang mở (accordion). Mặc định nhóm đầu. Bấm lại nhóm đang mở → thu. */
  private readonly openWrite = signal<string | null>(null);
  protected readonly openSection = computed<string | null>(() =>
    this.openWrite() ?? this.sections()[0]?.key ?? null);
  protected openSectionSet(k: string): void { this.openWrite.set(this.openSection() === k ? '__none__' : k); }

  protected readonly totalCount = computed(() => this.sections().length);
  protected readonly doneCount = computed(() => this.doneKeys().size);
  protected readonly percent = computed(() => {
    const t = this.totalCount();
    return t ? Math.round((this.doneCount() / t) * 100) : 0;
  });
}
