  protected readonly activeAnchor = signal('sg-info');
  private readonly anchorIds = ['sg-info', 'sg-adv', 'sg-cfg'];

  constructor() {
    // Scroll-spy: highlight mục nav theo thẻ gần đỉnh vùng cuộn.
    afterNextRender(() => this.setupScrollSpy());
  }

  /** Bấm mục nav con → cuộn mượt tới thẻ tương ứng + set active. */
  protected onNav(it: { key: string }): void {
    if (!this.anchorIds.includes(it.key)) return;
    const el = this.hostEl.nativeElement.querySelector('#' + it.key) as HTMLElement | null;
    if (!el) return;
    el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    this.activeAnchor.set(it.key);
  }

  private setupScrollSpy(): void {
    const root = this.hostEl.nativeElement.querySelector('.sgp-scroll') as HTMLElement | null;
    if (!root) return;
    const els = this.anchorIds
      .map((id) => root.querySelector('#' + id) as HTMLElement | null)
      .filter((e): e is HTMLElement => !!e);
    if (!els.length) return;
    const LINE = 140; // px dưới đỉnh vùng cuộn = mốc kích hoạt mục nav.
    const update = (): void => {
      const rootTop = root.getBoundingClientRect().top;
      let cur = els[0].id;
      for (const el of els) {
        if (el.getBoundingClientRect().top - rootTop <= LINE) cur = el.id;
      }
      // Cuộn chạm đáy: thẻ cuối không thể lên đỉnh (thiếu nội dung dưới) → ép active thẻ cuối.
      if (root.scrollTop + root.clientHeight >= root.scrollHeight - 2) cur = els[els.length - 1].id;
      this.activeAnchor.set(cur);
    };
    root.addEventListener('scroll', update, { passive: true });
    update();
  }

